import{_ as s,C as a,o as i,c as l,j as t,a as o,E as n,a6 as c}from"./chunks/framework.CD0vXS2f.js";const b=JSON.parse('{"title":"05 · Game-Day Failover Drills, Snapshot Drift & B1–B12 Standard","description":"Repeatable quarterly Game-Day failover protocol, model snapshot parity checks, and the 12-point Multi-Region BCP Readiness Standard (B1–B12).","frontmatter":{"title":"05 · Game-Day Failover Drills, Snapshot Drift & B1–B12 Standard","description":"Repeatable quarterly Game-Day failover protocol, model snapshot parity checks, and the 12-point Multi-Region BCP Readiness Standard (B1–B12)."},"headers":[],"relativePath":"playbooks/multi-region-bcp/05-gameday-failover-drills.md","filePath":"playbooks/multi-region-bcp/05-gameday-failover-drills.md","lastUpdated":1795280666087}'),p={name:"playbooks/multi-region-bcp/05-gameday-failover-drills.md"};function g(y,e,u,h,f,m){const r=a("PlaybookMeta"),d=a("PageBrief");return i(),l("div",null,[e[0]||(e[0]=t("h1",{id:"_05-·-game-day-failover-drills-snapshot-drift-b1–b12-standard",tabindex:"-1"},[o("05 · Game-Day Failover Drills, Snapshot Drift & "),t("code",null,"B1–B12"),o(" Standard "),t("a",{class:"header-anchor",href:"#_05-·-game-day-failover-drills-snapshot-drift-b1–b12-standard","aria-label":'Permalink to "05 · Game-Day Failover Drills, Snapshot Drift & `B1–B12` Standard"'},"​")],-1)),n(r,{track:"03 · Multi-Region Foundry BCP, Residency & Failover Drills",verified:"2026-11-19 PST",status:"Live v2.0",kitHref:"/papers/engineering-kits#bcp-kql",printable:""}),n(d,{stage:"govern",readTime:"4 min read",problem:"Secondary DR stamps rot silently when primary deployments upgrade model snapshots, rotate RBAC roles, or outgrow secondary PAYG TPM quotas.",takeaway:"Run automated daily snapshot-parity probes plus a 30-minute quarterly Game-Day cutover drill verified by the B1–B12 BCP Readiness Standard.",csaUse:"Execute the 5-step Game-Day runbook below in non-peak windows and archive the KQL telemetry output for compliance sign-off."}),e[1]||(e[1]=c('<h2 id="_1-five-step-quarterly-game-day-drill-protocol-validate" tabindex="-1">1. Five-Step Quarterly Game-Day Drill Protocol <code>[Validate]</code> <a class="header-anchor" href="#_1-five-step-quarterly-game-day-drill-protocol-validate" aria-label="Permalink to &quot;1. Five-Step Quarterly Game-Day Drill Protocol `[Validate]`&quot;">​</a></h2><ol><li><strong>Pre-Flight Drift Check (<code>T - 15 min</code>):</strong> Verify identical model name, version snapshot string, content-filter policy name, APIM Managed Identity RBAC (<code>Cognitive Services OpenAI User</code>), and Secondary AI Search document count parity (<code>≤1%</code> delta).</li><li><strong>Synthetic Canary Cutover (<code>T + 0 min</code>):</strong> Apply an APIM inbound test header (<code>x-bcp-drill: force-secondary</code>) or trip Priority-1 health status for a <code>10%</code> canary slice, then ramp to <code>100%</code> traffic onto Secondary Stamp B.</li><li><strong>Cold-Cache Surge Observation (<code>T + 0..15 min</code>):</strong> Run <a href="/enterprise-azure-ai-hub/papers/engineering-kits#bcp-kql"><code>bcp-failover-readiness-gate.kql</code></a> to measure: <ul><li>Cutover RTO (<code>time from primary 503/429 injection to first HTTP 200 on Secondary Stamp B</code>).</li><li>Cold-cache peak TPM absorbed without surfacing HTTP <code>429</code> to end users.</li><li>Time for Secondary <code>CachedSharePct</code> to climb from <code>0%</code> above <code>60%</code>.</li></ul></li><li><strong>Stateful Turn Continuity Test (<code>T + 15 min</code>):</strong> Start a multi-turn agent thread in Stamp A, force mid-conversation failover to Stamp B, upload/query a grounded document, and verify zero Cosmos DB checkpoint loss and valid AI Search citations.</li><li><strong>Failback &amp; Evidence Sign-Off (<code>T + 30 min</code>):</strong> Restore Priority-1 routing to Stamp A, verify automatic circuit-breaker healing, and export the KQL drill record for Risk/Audit retention.</li></ol><h3 id="snapshot-evidence-must-include-the-expected-secondary" tabindex="-1">Snapshot Evidence Must Include the Expected Secondary <a class="header-anchor" href="#snapshot-evidence-must-include-the-expected-secondary" aria-label="Permalink to &quot;Snapshot Evidence Must Include the Expected Secondary&quot;">​</a></h3><p>A per-region healthy KQL row cannot prove cross-region parity: two regions can each report one <strong>different</strong> snapshot, and a silent secondary emits no row at all. Before <code>B2</code>/<code>B11</code> sign-off, run the <a href="/enterprise-azure-ai-hub/papers/engineering-kits#fail-closed-cross-region-snapshot-evidence">offline snapshot companion gate</a> on the drill&#39;s exported KQL result objects against an independently approved model/region manifest. It requires positive call evidence from every expected region and an exact match to the pinned snapshot, rejecting unknown snapshots, duplicates, and unexpected stamps <span class="ev-badge ev-arch">[Arch]</span>.</p><p>Send synthetic probes to the standby during the selected lookback window; absence of secondary evidence must block sign-off, not count as a healthy standby. Snapshot success does not validate content-filter parity or replace the live failover and stateful-continuity checks above <span class="ev-badge ev-val">[Validate]</span>.</p><p>Freshness must be checked <strong>per stamp</strong>: an active primary must not hide an old secondary observation or a replayed export. The companion requires the updated query&#39;s <code>LastSeen</code> timestamp and rejects missing, timezone-less, future, or stale values <span class="ev-badge ev-arch">[Arch]</span>. Its default maximum age is <strong>15 minutes</strong>, configurable with a positive integer <code>--max-age-minutes</code> to match the approved probe cadence; this is a local readiness threshold, not an Azure guarantee <span class="ev-badge ev-agree">[Agree]</span>.</p><p>Fresh traffic must also include <strong>successful inference</strong>, not just recent failures. The updated query exports <code>SuccessfulCalls</code> and <code>LastSuccessfulSeen</code> from instrumented model dependencies with HTTP <code>200–299</code>; the companion requires a positive successful-call count no greater than <code>TotalCalls</code> and applies the same freshness limit to the last successful call. A standby returning only errors, or recent failures after an old success, must block snapshot sign-off. Regenerate older exports rather than substituting <code>LastSeen</code> for <code>LastSuccessfulSeen</code> <span class="ev-badge ev-arch">[Arch]</span>. HTTP <code>2xx</code> alone does not establish completed streaming output, stateful continuity, or the full readiness standard; keep the live drill checks <span class="ev-badge ev-val">[Validate]</span>.</p><hr><h2 id="_2-the-12-point-multi-region-bcp-readiness-standard-b1–b12-agree" tabindex="-1">2. The 12-Point Multi-Region BCP Readiness Standard (<code>B1–B12</code>) <code>[Agree]</code> <a class="header-anchor" href="#_2-the-12-point-multi-region-bcp-readiness-standard-b1–b12-agree" aria-label="Permalink to &quot;2. The 12-Point Multi-Region BCP Readiness Standard (`B1–B12`) `[Agree]`&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Gate ID</th><th style="text-align:left;">Category</th><th style="text-align:left;">Verification Requirement</th><th style="text-align:left;">Target Pass Bar</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>B1</code></strong></td><td style="text-align:left;">Residency Symmetry</td><td style="text-align:left;">Primary, local spillover, and secondary DR deployments all enforce the <strong>same or stricter</strong> geographic scope (<code>DataZone</code> or <code>Regional</code>) <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;">Verified in Azure Policy</td></tr><tr><td style="text-align:left;"><strong><code>B2</code></strong></td><td style="text-align:left;">Snapshot Parity</td><td style="text-align:left;">Primary and Secondary Foundry deployments pin the <strong>exact same model version snapshot</strong> and <code>contentFilter</code> configuration.</td><td style="text-align:left;"><code>0</code> version drift</td></tr><tr><td style="text-align:left;"><strong><code>B3</code></strong></td><td style="text-align:left;">Cold-Cache Quota</td><td style="text-align:left;">Secondary region&#39;s <code>Standard</code> + <code>PTU-M</code> TPM quota is <code>≥ 2.6×</code> primary steady cached Normalized TPM to survive cold-cache hydration.</td><td style="text-align:left;">Quota verified</td></tr><tr><td style="text-align:left;"><strong><code>B4</code></strong></td><td style="text-align:left;">Zone Redundancy</td><td style="text-align:left;">Intra-region Availability Zones (<code>ZRS</code>) enabled on APIM, Cosmos DB, ADLS Gen2, AI Search (<code>≥2–3</code> replicas), and ACA environment <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;"><code>100%</code> ZRS where supported</td></tr><tr><td style="text-align:left;"><strong><code>B5</code></strong></td><td style="text-align:left;">Stateless Threading</td><td style="text-align:left;">Agent conversation state is persisted in multi-region Cosmos DB (<code>Model 2</code>), never trapped in single-region in-memory / server state.</td><td style="text-align:left;">Verified mid-thread cutover</td></tr><tr><td style="text-align:left;"><strong><code>B6</code></strong></td><td style="text-align:left;">Search Index Parity</td><td style="text-align:left;">Secondary Azure AI Search stamp indexes continuously from <code>RA-GZRS</code> ADLS Gen2 with <code>&lt;1%</code> document count lag <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;">Automated lag alert</td></tr><tr><td style="text-align:left;"><strong><code>B7</code></strong></td><td style="text-align:left;">Sandbox Pool Parity</td><td style="text-align:left;">Secondary ACA Dynamic Session Pool / Sandbox Group is deployed with matching container image SHA tag (never <code>:latest</code>).</td><td style="text-align:left;">Exact SHA match</td></tr><tr><td style="text-align:left;"><strong><code>B8</code></strong></td><td style="text-align:left;">Keyless DR Auth</td><td style="text-align:left;">Secondary APIM + ACA Managed Identities hold pre-assigned RBAC roles on Secondary Foundry, Cosmos, Search, and ADLS <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;">Verified by synthetic probe</td></tr><tr><td style="text-align:left;"><strong><code>B9</code></strong></td><td style="text-align:left;">Automated Cutover</td><td style="text-align:left;">APIM Backend Pool circuit breaker switches inference traffic on <code>429</code> / <code>5xx</code> without manual DNS or portal edits <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;"><code>&lt;15s</code> cutover RTO</td></tr><tr><td style="text-align:left;"><strong><code>B10</code></strong></td><td style="text-align:left;">Synthetic Probe</td><td style="text-align:left;">Lightweight 5-minute synthetic health probe verifies Secondary Foundry + Search availability (<code>&lt;1,024</code> tokens, cache writes off).</td><td style="text-align:left;"><code>99.9%</code> probe pass</td></tr><tr><td style="text-align:left;"><strong><code>B11</code></strong></td><td style="text-align:left;">Workpaper Lineage</td><td style="text-align:left;">Failover responses record actual executing region/stamp and model snapshot in OpenTelemetry / workpaper audit logs.</td><td style="text-align:left;">Verified in App Insights</td></tr><tr><td style="text-align:left;"><strong><code>B12</code></strong></td><td style="text-align:left;">Quarterly Game-Day</td><td style="text-align:left;">Full 30-minute Game-Day drill executed and signed off within the last 90 days (and prior to major seasonal filing cliffs).</td><td style="text-align:left;">Signed KQL evidence</td></tr></tbody></table>',10))])}const x=s(p,[["render",g]]);export{b as __pageData,x as default};
